def is_majority(arr, n, element):
    if arr is None or n <= 0:
        return False

    n = min(n, len(arr))
    if n <= 0:
        return False

    def lower_bound(x):
        lo, hi = 0, n
        while lo < hi:
            mid = (lo + hi) // 2
            if arr[mid] < x:
                lo = mid + 1
            else:
                hi = mid
        return lo

    def upper_bound(x):
        lo, hi = 0, n
        while lo < hi:
            mid = (lo + hi) // 2
            if arr[mid] <= x:
                lo = mid + 1
            else:
                hi = mid
        return lo

    first = lower_bound(element)
    last_exclusive = upper_bound(element)
    count = last_exclusive - first

    return count * 2 > n


