def minPath(grid, k):
    if k <= 0:
        return []

    n = len(grid)

    min_val = None
    r = c = 0
    for i in range(n):
        for j in range(n):
            v = grid[i][j]
            if min_val is None or v < min_val:
                min_val = v
                r, c = i, j

    path = [min_val]
    if k == 1:
        return path

    directions = ((1, 0), (-1, 0), (0, 1), (0, -1))

    for _ in range(k - 1):
        best_val = None
        best_r = best_c = None

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n:
                v = grid[nr][nc]
                if best_val is None or v < best_val:
                    best_val = v
                    best_r, best_c = nr, nc

        path.append(best_val)
        r, c = best_r, best_c

    return path
