def magic_square_test(matrix):
    try:
        rows = list(matrix)
    except TypeError:
        return False

    n = len(rows)
    if n == 0:
        return False

    try:
        rows = [list(row) for row in rows]
    except (TypeError, ValueError):
        return False

    if any(len(row) != n for row in rows):
        return False

    try:
        target = sum(rows[0])

        for i in range(n):
            if sum(rows[i]) != target:
                return False
            if sum(rows[j][i] for j in range(n)) != target:
                return False

        if sum(rows[i][i] for i in range(n)) != target:
            return False

        if sum(rows[i][n - 1 - i] for i in range(n)) != target:
            return False

    except (TypeError, ValueError, IndexError):
        return False

    return True


