def is_samepatterns(sequence, patterns):
    """
    Return True if `sequence` follows the same one-to-one pattern as `patterns`.

    The function checks that:
    - Both inputs have the same length.
    - Equal elements in `patterns` correspond to equal elements in `sequence`.
    - Distinct elements in `patterns` correspond to distinct elements in `sequence`.
    """
    if isinstance(sequence, str):
        sequence = list(sequence)
