from typing import List

class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        mentions = [0] * numberOfUsers

        # return_time[user] is the timestamp when an offline user becomes online again.
        # Initially all users are online, so use a time before all possible timestamps.
        return_time = [-1] * numberOfUsers

        # Process events in chronological order.
        # At the same timestamp, OFFLINE events are processed before MESSAGE events.
        ordered_events = sorted(
            events,
            key=lambda event: (int(event[1]), 0 if event[0] == "OFFLINE" else 1)
        )

        for event in ordered_events:
            timestamp = int(event[1])

            if event[0] == "OFFLINE":
                user = int(event[2])

                # The problem guarantees this user is online at this timestamp.
                # The check also makes the logic robust if duplicate invalid events appear.
                if return_time[user] <= timestamp:
                    return_time[user] = timestamp + 60

            else:  # MESSAGE
                for token in event[2].split():
                    if token == "ALL":
                        for user in range(numberOfUsers):
                            mentions[user] += 1

                    elif token == "HERE":
                        for user in range(numberOfUsers):
                            if return_time[user] <= timestamp:
                                mentions[user] += 1

                    else:  # id<number>
                        user = int(token[2:])
                        if 0 <= user < numberOfUsers:
                            mentions[user] += 1

        return mentions
