from typing import List

class Solution:
    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        limit = max(groups)
        INF = len(elements)

        first_index = [INF] * (limit + 1)
        unique_values = []

        for idx, val in enumerate(elements):
            if val <= limit and first_index[val] == INF:
                first_index[val] = idx
                unique_values.append(val)

        assigned = [INF] * (limit + 1)

        for val in unique_values:
            idx = first_index[val]
            for multiple in range(val, limit + 1, val):
                if idx < assigned[multiple]:
                    assigned[multiple] = idx

        return [-1 if assigned[g] == INF else assigned[g] for g in groups]
