class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        def get_substrings(x: str) -> set:
            n = len(x)
            return {x[i:j] for i in range(n + 1) for j in range(i, n + 1)}

        s_parts = sorted(get_substrings(s), key=len, reverse=True)
        t_parts = sorted(get_substrings(t), key=len, reverse=True)

        best = 0
        max_t_len = len(t)

        for a in s_parts:
            len_a = len(a)
            if len_a + max_t_len <= best:
                break

            for b in t_parts:
                total = len_a + len(b)
                if total <= best:
                    break

                candidate = a + b
                if candidate == candidate[::-1]:
                    best = total

        return best
